function getSmallestString(s) {
  // Try every allowed swap (and no swap at all) and keep the smallest result.
  let best = s;
  for (let i = 0; i + 1 < s.length; i++) {
    if ((s.charCodeAt(i) - s.charCodeAt(i + 1)) % 2 !== 0) continue;
    const chars = [...s];
    const held = chars[i];
    chars[i] = chars[i + 1];
    chars[i + 1] = held;
    const candidate = chars.join('');
    if (candidate < best) best = candidate;
  }
  return best;
}

