function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 80 + Math.floor(rand() * 21) : 2 + Math.floor(rand() * 7);
  // The first "calm" characters never offer a useful swap, which moves the answer's swap further right (or removes it).
  const calm = Math.floor(rand() * (n + 1));
  let s = '';
  for (let i = 0; i < n; i++) {
    let digit = Math.floor(rand() * 10);
    if (i > 0 && i < calm) {
      const before = Number(s[i - 1]);
      while (digit % 2 === before % 2 && digit < before) digit = Math.floor(rand() * 10);
    }
    s += digit;
  }
  return [s];
}
